'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const outlineIco=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plane:'<path d="m3 9 7 2 7-7c2-2 4-1 2 2l-6 8 1 6-3 1-3-6-5-3Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',walk:'<circle cx="14" cy="3" r="2"/><path d="m7 21 4-7 3 2 3 5M11 14l2-7 3 4 4 1M13 7l-4 3-3 1"/>',bed:'<path d="M3 5v16m18-9v9M3 17h18M3 12h18v5H3Zm2-4h5v4H5Z"/>',hotel:'<path d="M4 21V6l8-3 8 3v15M2 21h20M9 21v-6h6v6M8 8h1m6 0h1M8 11h1m6 0h1"/>',map:'<path d="m2 5 6-2 8 3 6-2v15l-6 2-8-3-6 2Zm6-2v15m8-12v15"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h2m4 0h2m-8 3h2"/>',ticket:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4Zm12 0v3m0 3v2m0 3v3"/>',book:'<path d="M12 5C9 2 5 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-7-2-10 1Zm0 0v16"/>',food:'<path d="M5 3v7m-3-7v5c0 4 6 4 6 0V3M5 11v10M17 3c-4 5-4 10 0 10V3Zm0 10v8"/>',car:'<path d="m5 7 2-4h10l2 4 2 3v8H3v-8Zm-2 3h18M6 18v3m12-3v3M6 14h2m8 0h2"/>',warn:'<path d="m12 3 10 18H2Zm0 6v5m0 3v.1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',check:'<path d="m4 12 5 5L20 6"/>',phone:'<path d="m6 3 4 4-2 3c2 3 4 5 6 6l3-2 4 4c-3 6-8 2-12-2S0 6 6 3Z"/>',bag:'<path d="M4 7h16v14H4Zm4 0V5a4 4 0 0 1 8 0v2"/>',pin:'<path d="M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>'})[n]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
const solidGlyphs={
 pin:'<path fill-rule="evenodd" d="M12 1.5a8 8 0 0 0-8 8C4 15 12 23 12 23s8-8 8-13.5a8 8 0 0 0-8-8Zm0 4.5a3.4 3.4 0 1 1 0 6.8A3.4 3.4 0 0 1 12 6Z"/>',
 plane:'<path d="m22 3-1-1a2 2 0 0 0-2 .4l-5.8 5.8L4 6 1.8 8.2l8.4 4.9-4.3 4.3-3.1-.4-1.3 1.3 4.2 1.5 1.5 4.2 1.3-1.3-.4-3.1 4.3-4.3 4.9 8.4 2.2-2.2-2.2-9.2 5.8-5.8A2 2 0 0 0 22 3Z" transform="translate(0 -1) scale(.96)"/>',
 bed:'<path d="M2 4h2v10h16V9h2v13h-2v-5H4v5H2Z"/><path d="M5 8h5v5H5Zm7 2h8v3h-8Z"/>',
 walk:'<circle cx="14" cy="3.2" r="2.2"/><path d="m13 6-4 2.8-3 1.3.8 2 3.6-1.5 1.5-1.2-1.7 6-3.5 6.2 2.1 1.1 3.6-6.3 1.9 1.4 2.4 4.8 2.1-1-2.8-5.5-2.6-2 1.1-4.3 1.9 2.2 4.1 1.2.6-2-3.6-1.1L15 6Z"/>',
 calendar:'<path fill-rule="evenodd" d="M6 1h2v3h8V1h2v3h2a2 2 0 0 1 2 2v15a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2V1Zm-2 9v11h16V10H4Zm3 3h3v3H7Zm7 0h3v3h-3Z"/>',
 ticket:'<path fill-rule="evenodd" d="M2 4h20v6a2 2 0 0 0 0 4v6H2v-6a2 2 0 0 0 0-4V4Zm12 2v3h2V6h-2Zm0 5v3h2v-3h-2Zm0 5v2h2v-2h-2Z"/>',
 food:'<path d="M2 1h1.6v6h1V1h1.6v6h1V1H9v6a4 4 0 0 1-2.7 3.8V23H4V10.8A4 4 0 0 1 2 7V1Zm16 0h2v22h-2V14h-4C14 6 15.2 2 18 1Z"/>',
 bag:'<path fill-rule="evenodd" d="M7 7V5a5 5 0 0 1 10 0v2h4v16H3V7h4Zm2 0h6V5a3 3 0 0 0-6 0v2Zm-2 3v3h2v-3H7Zm8 0v3h2v-3h-2Z"/>'
};
const ico=n=>solidGlyphs[n]?`<svg class="ink-glyph" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">${solidGlyphs[n]}</svg>`:outlineIco(n);

function inline(s){const text=String(s??''),rx=/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)|(https?:\/\/[^\s<>）)]+)/g;let out='',last=0,m;const fmt=t=>esc(t).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');while((m=rx.exec(text))){out+=fmt(text.slice(last,m.index));const url=m[2]||m[3];out+=`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(m[1]||url)} ↗</a>`;last=rx.lastIndex;}return out+fmt(text.slice(last));}
function markdown(s){s=s.replace(/^### 核查来源[^\n]*\n[\s\S]*?(?=^#{1,3} |$(?![\s\S]))/gm,'');const out=[],lines=s.split('\n');let list=false,table=[];const finish=()=>{if(table.length){const rows=table.filter(l=>!/^\s*\|?[\s:|-]+\|?\s*$/.test(l));out.push('<div class="table-scroll"><table>'+rows.map((l,i)=>'<tr>'+l.trim().replace(/^\||\|$/g,'').split('|').map(c=>`<${i?'td':'th'}>${inline(c.trim())}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</table></div>');table=[];}if(list){out.push('</ul>');list=false;}};for(const l of lines){if(l.trim().startsWith('|')){if(list){out.push('</ul>');list=false;}table.push(l);continue;}if(table.length)finish();let m;if((m=l.match(/^#{1,6}\s+(.+)/))){finish();out.push(`<h${l.startsWith('###')?3:2}>${inline(m[1])}</h${l.startsWith('###')?3:2}>`);}else if((m=l.match(/^\s*(?:[-*]|\d+[.、])\s+(.+)/))){if(!list){out.push('<ul>');list=true;}out.push('<li>'+inline(m[1])+'</li>');}else{finish();if(l.trim()&&!/^[-—]{3,}$/.test(l))out.push('<p>'+inline(l)+'</p>');}}finish();return out.join('');}
let state={day:1,view:'day',variants:{1:'A',10:'A'},transport:'train',checks:{}};
try{const saved=JSON.parse(localStorage.getItem('nordic-roadbook-v1')||'null');if(saved)state={...state,...saved,view:'day',day:Math.min(18,Math.max(1,+saved.day||1)),variants:{1:'A',10:'A',...saved.variants}};}catch{}
const persist=()=>{try{localStorage.setItem('nordic-roadbook-v1',JSON.stringify(state));}catch{}};
const clockLocation=(id=state.day)=>id===18?['北京','Asia/Shanghai']:id===1||id===17?['赫尔辛基','Europe/Helsinki']:id===16?['哥本哈根','Europe/Copenhagen']:id>=10?['冰岛','Atlantic/Reykjavik']:['挪威','Europe/Oslo'];
function clockBar(id=state.day){const [city,zone]=clockLocation(id);return `<div class="page-clock" aria-label="实时当地时间与北京时间"><div class="clock-item"><span class="clock-city">${esc(city)}</span><time class="clock-time" data-clock-zone="${zone}"></time></div><div class="clock-item"><span class="clock-city">北京</span><time class="clock-time" data-clock-zone="Asia/Shanghai"></time></div></div>`;}
function updateClocks(now=new Date()){document.querySelectorAll('[data-clock-zone]').forEach(t=>{const zone=t.dataset.clockZone;const parts=new Intl.DateTimeFormat('zh-CN',{timeZone:zone,month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(now);const get=k=>parts.find(x=>x.type===k)?.value||'';t.innerHTML=`<span class="clock-date">${get('month')}/${get('day')}</span> ${get('hour')}:${get('minute')}`;t.dateTime=now.toISOString();});}
const dateText=d=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const shortDate=d=>d.slice(5).replace('-',' / ');
const section=(title,en,body)=>`<section class="section"><div class="section-top"><div class="section-title"><span class="section-symbol">${ico(({TIMELINE:'calendar',PLACES:'pin',STAY:'bed',GROCERIES:'bag',OPTIONAL:'sun',STOPS:'bag',ACTIVITIES:'ticket',FLIGHTS:'plane',STAYS:'hotel'})[en]||'map')}</span><h2>${title}</h2></div><span class="section-kicker">${en}</span></div>${body}</section>`;
const mapSearch=q=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q);
const navLink=p=>p.mapUrl||mapSearch(p.mapQuery||(Number.isFinite(p.lat)&&Number.isFinite(p.lon)?p.lat+','+p.lon:p.en));
const hotelLink=k=>{const h=DATA.hotels[k];return mapSearch(h.name+' '+h.address);};
const navPoint=k=>k.startsWith('hotel:')?{name:DATA.hotels[k.slice(6)].cn,url:hotelLink(k.slice(6)),terms:[DATA.hotels[k.slice(6)].name,DATA.hotels[k.slice(6)].cn,'酒店','公寓']}:DATA.places[k]?{name:DATA.places[k].name,url:navLink(DATA.places[k]),terms:DATA.aliases?.[k]||[DATA.places[k].name,DATA.places[k].en]}:null;
function timelineText(r){const targets=(r.nav||[]).map(navPoint).filter(Boolean),used=new Set();const terms=targets.flatMap((p,i)=>p.terms.filter(t=>t.length>1).map(t=>({t,i}))).sort((a,b)=>b.t.length-a.t.length);const re=terms.length?new RegExp(terms.map(x=>x.t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'gi'):null;let out='',last=0,m;if(re)while((m=re.exec(r.text))){const term=terms.find(t=>t.t.toLowerCase()===m[0].toLowerCase()),p=targets[term.i];used.add(term.i);out+=inline(r.text.slice(last,m.index))+`<a class="place-inline" href="${esc(p.url)}" target="_blank" rel="noopener">${esc(m[0])}</a>`;last=re.lastIndex;}out+=inline(r.text.slice(last));const extra=targets.filter((p,i)=>!used.has(i));return out+(extra.length?`<div class="step-links">${extra.map(p=>ext(p.url,esc(p.name),'step-nav')).join('')}</div>`:'');}
function bookingNavigation(q){const p=DATA.places[q.meeting||q.spot];return `<div class="meeting-nav">${q.parking?`<div class="meeting-stop"><span>01 · 自驾停车</span><strong>${esc(DATA.places[q.parking].name)}</strong>${ext(navLink(DATA.places[q.parking]),'停车场导航','primary-link')}</div>`:''}<div class="meeting-stop"><span>${q.parking?'02 · 步行报到':'集合报到'}</span><strong>${esc(p.address||q.place)}</strong>${ext(navLink(p),'集合点导航','primary-link')}<button class="small-link" data-copy="${esc(p.address||q.place)}">复制集合地址 ${ico('check')}</button></div><p>${esc(q.walk||'')}</p>${q.day===13?'<p class="coordinate">票据GPS：64.048222, -16.180139</p>':''}</div>`;}
const ext=(url,label,cls='pill-link')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener">${label} ↗</a>`;
const pImage=k=>IMAGES[DATA.places[k]?.photo||k]||'';
const placeTips=p=>p.tips?.length?`<div class="detail-block"><h3>现场怎么逛</h3><ul class="place-tips">${p.tips.map(t=>`<li>${inline(t)}</li>`).join('')}</ul></div>`:'';
const photoCredit=k=>{const c=CREDITS[DATA.places[k]?.photo||k];return c?.license?[c.author,c.license,c.source,c.licenseUrl].filter(Boolean).join(' · '):'';};
let photoCard=(k,i)=>{const p=DATA.places[k],src=pImage(k);return !p||!src?'':`<button class="postcard" data-place="${esc(k)}" aria-label="查看${esc(p.name)}"><span class="postcard-index">${i+1}</span><span class="postcard-photo"><img src="${src}" alt="${esc(p.name)}" loading="lazy"></span><span class="postcard-footer"><span class="postcard-name">${ico('pin')}${esc(p.name)}</span><span class="arrow">${ico('arrow')}</span></span></button>`;};
function routeBoard(spots,id){return `<div class="route-board" data-photo-count="${spots.length}">${Array.from({length:Math.ceil(spots.length/2)},(_,g)=>{const pair=spots.slice(g*2,g*2+2);return `<div class="route-sheet ${pair.length===1?'single':''}"><svg class="route-thread" aria-hidden="true"><path class="route-underlay" fill="none"/><path class="route-ink" fill="none"/><g class="route-nodes"></g></svg>${pair.map((k,i)=>photoCard(k,g*2+i)).join('')}${id===1&&g===0&&pair.length===2?`<div class="route-caption">${ico('walk')}<span>步行20–25分钟</span></div>`:''}</div>`;}).join('')}</div>`;}

function timeline(rows){return `<div class="timeline">${rows.map(r=>`<div class="timeline-row ${/集合|报到|还车|采购|放行|自带|蓝调|不会游泳/.test(r.text)?'important':''}"><div class="timeline-time">${inline(r.time)}</div><div class="timeline-text">${timelineText(r)}</div></div>`).join('')}</div>`;}
function flight(f){return `<div class="flight"><div class="flight-top"><strong>${esc(f[0])}</strong><span>${esc(f[1])} → ${esc(f[4])}</span></div><div class="flight-route"><div class="flight-dest"><div class="flight-time">${esc(f[3])}</div><div class="flight-city">${esc(f[2])}</div></div><div class="flight-line">${ico('plane')}</div><div class="flight-dest"><div class="flight-time">${esc(f[6].split(' ')[0])}${f[6].includes('+')?'<span> +1日</span>':''}</div><div class="flight-city">${esc(f[5])}</div></div></div></div>`;}
function booking(b){return `<div class="booking"><button data-booking="${b.day}" aria-label="查看${esc(b.name)}订单信息"><div class="booking-head"><span>${esc(b.name)}</span><span>${b.people}位 · 已订</span></div><div class="booking-time">${esc(b.time)}</div><div class="booking-report"><span>路书报到目标</span><strong>${esc(b.report)}</strong></div><div class="booking-note">${esc(b.note)}</div></button></div>`;}
function hotelButton(key){const h=DATA.hotels[key];return h?`<button class="hotel" data-hotel="${key}"><span class="hotel-icon">${ico('bed')}</span><span class="hotel-copy"><strong>${esc(h.cn)}</strong><small>${esc(h.name)}</small></span><span class="arrow">${ico('arrow')}</span></button>`:'';}
function stayFooter(key){const h=DATA.hotels[key];return h?section('今晚住宿','STAY',`<div class="stay-card">${hotelButton(key)}<p class="stay-address">${esc(h.address)}</p><p class="stay-note">${esc(h.note)}</p><div class="stay-actions">${ext(hotelLink(key),'导航到酒店','primary-link')}<button class="small-link" data-copy="${esc(h.name+'\n'+h.address)}">复制地址 ${ico('check')}</button></div></div>`):'';}
function venueCard(k){const p=DATA.places[k];if(!p)return '';const src=pImage(k);return `<div class="venue-card"><button class="venue-title" data-venue="${esc(k)}">${ico(/麦当劳|晚餐/.test(p.name)?'food':/超市|Krónan|Joker|SPAR|百货|设计|购物|编织/.test(p.name)?'bag':'pin')}<span><strong>${esc(p.name)}</strong><small>${esc(p.stay||'按当日安排')}</small></span>${ico('arrow')}</button><div class="venue-body"><p>${inline(p.desc)}</p>${src?`<button class="venue-thumb" data-venue="${esc(k)}" aria-label="查看${esc(p.name)}图片与简介"><img src="${src}" alt="${esc(p.name)}${k==='handknit'?' · 羊毛衫商品':''}" loading="lazy"></button>`:''}</div><div class="venue-actions"><button data-venue="${esc(k)}" class="small-link">详情 ${ico('arrow')}</button>${ext(navLink(p),'导航','small-link')}</div></div>`;}

function transportBox(){const t={train:{name:'往返列车',price:'€36–38.40 / 4人往返',text:'机场站↔中央车站，I/P线约30分钟；含酒店步行、候车每程留45–60分钟。ABC单程App/机器€4.50，感应支付€4.80/人。',window:'完整夜游需20:15前到中央车站。四箱留酒店；晚到缩减为车站附近，或直接选A。'},taxi:{name:'往返打车',price:'约 €76–84 / 4人往返',text:'每程留30–45分钟。机场官方固定价约€38–40起，酒店上车与返程须先确认报价；晚间供车可变化。',window:'20:30前到中央车站较从容，最晚20:45。21:20先查看供车，21:50叫车，22:00前上车。'},mixed:{name:'列车去 · 打车回',price:'约 €56–60 / 4人往返',text:'去程四人ABC票€18–19.20；回程出租车约€38–40起。须提前看返程供车与报价。',window:'去程20:15前到中央车站；21:20查看供车，22:00前上车。叫不到车则按21:53 P线返程。'}}[state.transport];return `<div class="transport-grid">${['train','taxi','mixed'].map(k=>`<button data-transport="${k}" aria-pressed="${k===state.transport}">${{train:'往返列车',taxi:'往返打车',mixed:'列车去 · 打车回'}[k]}</button>`).join('')}</div><div class="transport-price">${t.price}</div><p class="intro-text">${t.text}</p><div class="callout">${ico('calendar')}<span>${t.window}</span></div><button class="small-link" data-detail="heltransport">返程车次与容错时间 ${ico('arrow')}</button>`;}
function renderDay(){const d=DATA.days[state.day-1],variant=d.variants?.[state.variants[d.id]||'A'];const titles={2:'转机日',3:'缆车蓝调',4:'特罗姆瑟观鲸',5:'罗弗敦',6:'Nusfjord · Å',7:'雷讷海岸',8:'前往博德',9:'奥斯陆',10:'冰岛温泉',11:'南岸瀑布',12:'冰河湖',13:'蓝冰洞',14:'黄金圈',15:'Silfra浮潜',16:'哥本哈根',17:'赫尔辛基转机',18:'北京抵达'};let html=`<header class="page-header"><div class="eyebrow">2026 · ${dateText(d.date)} · ${d.region}</div><div class="day-ghost">${String(d.id).padStart(2,'0')}</div><h1 class="${(titles[d.id]||d.title).length>5?'long-title':''}">${esc(titles[d.id]||d.title)}</h1><p class="en">${esc(d.en)}</p><div class="sun">${ico('sun')}<span>日出约 ${d.sun[0]}<br class="mobile-break"> 日落约 ${d.sun[1]}</span><span class="tz-label">· ${esc(d.tz)}</span></div>${d.id!==18?`<img class="header-art ${[1,2,9,17].includes(d.id)?'cutout':''}" src="${ART[d.art]}" alt="">`:''}</header>`;
 if(d.flights?.length)html+=`<div class="flights">${d.flights.map(flight).join('')}</div>`;
 html+=DATA.bookings.filter(b=>b.day===d.id).map(booking).join('');
 if(d.alert&&![1,12,13,15].includes(d.id))html+=`<div class="callout">${ico('warn')}<span>${inline(d.alert)}</span></div>`;

 if(d.timeline?.length)html+=section('当天安排','TIMELINE',`<div class="time-legend" aria-label="时间标记说明"><span><i></i>关键时间</span><span class="legend-current"><i></i>当前</span><span class="legend-next"><i></i>下一段</span><small>按计划时间</small></div>${timeline(d.timeline)}`);
 if(variant){html+=`<div class="choice" role="group" aria-label="路线选择" data-selected="${state.variants[d.id]||'A'}">${Object.entries(d.variants).map(([k,v])=>`<button data-variant="${k}" aria-pressed="${k===(state.variants[d.id]||'A')}"><b>${k}</b><span>${esc(v.label)}</span></button>`).join('')}</div><div class="variant-content">`;
 if(d.id===1&&state.variants[1]==='B')html+=transportBox();
 let vr=variant.timeline;if(d.id===1&&state.variants[1]==='B')vr=vr.filter(r=>state.transport==='train'?r.time!=='22:00前':r.time!=='21:45');
 html+=timeline(vr)+'</div>';}
 if(d.id!==1)html+=`<div class="meal-line">${ico('food')}<span>${inline(d.meal)}</span></div>`;
 const spots=(variant?variant.spots:d.spots).filter(k=>pImage(k));
 if(spots.length)html+=section('沿途停留','PLACES',`${routeBoard(spots,d.id)}`);
 if(d.venues?.length)html+=section('打卡 · 购物 · 补给','STOPS',`<div class="venue-grid">${d.venues.map(venueCard).join('')}</div>`);
 if(d.drive)html+=`<div class="mini-info">${ico('car')} ${inline(d.drive)}</div>`;
 if(d.id===11)html+=section('四晚厨房采购','GROCERIES',`<div class="mini-info">17:30–18:30 · Krónan Vík<br>28—31日晚餐共16人份；另备早餐、路上午餐。29、30日食材用保温袋冷藏；31日优先意面、米饭、罐头等耐储食品。</div><button class="small-link" data-detail="groceries">打开采购清单 ${ico('arrow')}</button>`);
 if(d.id===13)html+=section('留守同伴 · Hali','NEAR THE HOTEL',`<p class="intro-text">优先酒店旁Þórbergssetur书墙与文化馆；外观10–15分钟，开放时入内45–60分钟。咖啡馆常规11:00–15:00，馆内时段向前台核实。只走酒店周边平坦短路，风雨大时留室内；不步行前往冰河湖。</p>`);
 if(d.id===15)html+=section('留守同伴 · 集合点','NEAR SILFRA',`<p class="intro-text">在P5与集合点附近等候，可沿安全步道看教堂和农舍外观，往返约30–45分钟。保留车钥匙和保暖衣物；地面结冰、强风时回车内，不独自远走峡谷或沿车道步行。</p>`);
 if(d.alternatives?.length)html+=section('备选安排','OPTIONAL',`<div class="alt-list">${d.alternatives.map(a=>`<div class="alt-row"><strong>${esc(a.name)}</strong><p>${inline(a.text)}</p>${a.spot?`<button class="small-link" data-venue="${a.spot}">查看景点 ${ico('arrow')}</button> ${ext(navLink(DATA.places[a.spot]),'导航','small-link')}`:''}</div>`).join('')}</div>`);
 let guide=d.id>=5&&d.id<=8?'norway':d.id>=10&&d.id<=15?'iceland':'';
 html+=`<div class="guide-links"><button class="pill-link" data-notes="${d.id}">当日详细说明 ${ico('book')}</button>${guide?`<button class="pill-link" data-guide="${guide}">自驾 · 付款与罚单 ${ico('car')}</button>`:''}${(d.id!==1||state.variants[1]==='B')?`<button class="pill-link" data-mapday="${d.id}">路线地图 ${ico('map')}</button>`:''}</div>`;
 if(d.hotel)html+=stayFooter(d.hotel);
 html+=`<div class="next-prev"><button data-day="${d.id-1}" ${d.id===1?'disabled':''}>${ico('back')} 前一天</button><span>${String(d.id).padStart(2,'0')} / 18</span><button data-day="${d.id+1}" ${d.id===18?'disabled':''}>后一天 ${ico('arrow')}</button></div>`;
 return html;}
function atlas(){const merc=lat=>Math.log(Math.tan(Math.PI/4+lat*Math.PI/360));const project=([lon,lat])=>[(lon+26)/60*680,24+(merc(71.5)-merc(lat))/(merc(71.5)-merc(54))*382];let shapes='';for(const f of GEO.features){const polys=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];for(const poly of polys){const path=poly.map(r=>r.map((c,i)=>{const p=project(c);return (i?'L':'M')+p.map(n=>n.toFixed(1)).join(' ');}).join(' ')+'Z').join(' ');shapes+=`<path class="land" d="${path}"/>`;}}const keys=['hel-airport','tos-airport','lkn-airport','boo-airport','osl-airport','kef-airport','cph-airport','hel-airport'];const points=keys.map(k=>{const p=DATA.places[k];return project([p.lon,p.lat]);});let route=points.map((p,i)=>`${i?'L':'M'}${p.join(' ')}`).join(' ');const thumbs=[['jokulsarlon',120,168,39,'冰岛',120,230],['hamnoy',430,150,38,'挪威',430,208],['cathedral',590,285,35,'芬兰',590,340],['nyhavn',353,356,34,'丹麦',353,410]];return `<div class="journey-atlas"><svg class="atlas" viewBox="0 0 680 430" role="img" aria-label="冰岛与北欧航线概览"><rect class="water" width="680" height="430"/>${shapes}<path class="route" d="${route}"/>${points.slice(0,-1).map(p=>`<circle class="node" cx="${p[0]}" cy="${p[1]}" r="5"/>`).join('')}<text class="ocean" x="30" y="335">NORTH ATLANTIC</text><text x="70" y="110">冰岛</text><text x="430" y="125">挪威</text><text x="560" y="255">芬兰</text><text x="350" y="392">丹麦</text></svg><div class="atlas-photos">${[['jokulsarlon','冰岛'],['hamnoy','挪威'],['cathedral','芬兰'],['nyhavn','丹麦']].map(([k,n])=>`<figure><img src="${pImage(k)}" alt="${esc(DATA.places[k].name)}" loading="lazy"><figcaption>${n}</figcaption></figure>`).join('')}</div></div>`;}
function overview(){return `<div class="view-top"><div class="eyebrow">THE NORDIC JOURNEY · 18 DAYS</div><h1>北境全程</h1><p class="intro-text">2026.10.18 — 11.04　北京 · 北欧 · 冰岛</p></div><button data-mapday="all" aria-label="打开全程互动地图" style="padding:0;width:100%">${atlas()}</button><button class="primary-link" data-mapday="all">展开全程地图 ${ico('map')}</button>${DATA.days.map(d=>{let k=(d.id===1?['station']:d.spots).find(p=>pImage(p));return `<button class="overview-item" data-day="${d.id}"><span class="n">${String(d.id).padStart(2,'0')}</span><span><span class="d">${shortDate(d.date)} · ${d.region}</span><strong>${esc(d.title)}</strong></span>${k?`<img src="${pImage(k)}" alt="" loading="lazy">`:`<span>${ico(d.flights?.length?'plane':'hotel')}</span>`}${ico('arrow')}</button>`;}).join('')}`;}
function orders(){return `<div class="view-top"><div class="eyebrow">RESERVATIONS</div><h1>航班与订单</h1><p class="intro-text">以下均为当地时间</p></div>${section('已订活动','ACTIVITIES',DATA.bookings.map(b=>`<div class="section-top"><button class="small-link" data-day="${b.day}">${dateText(DATA.days[b.day-1].date)}</button></div>${booking(b)}`).join(''))}${section('航班一览','FLIGHTS',DATA.days.filter(d=>d.flights?.length).map(d=>`<div class="section-top"><button class="small-link" data-day="${d.id}">${dateText(d.date)} ${ico('arrow')}</button></div><div class="flights">${d.flights.map(flight).join('')}</div>`).join(''))}${section('住宿','STAYS',Object.entries(DATA.hotels).map(([k,h])=>hotelButton(k)).join(''))}`;}
function memo(){const items=[['norway','挪威自驾','停车、过路费、隧道放行、罚单','car'],['iceland','冰岛自驾','Parka / Checkit、停车机、罚单与还车','car'],['groceries','厨房采购','10月28—31日 · 四晚做饭','bag'],['packing','出发清单','证件、保暖、活动与行李','check'],['emergency','应急资源','紧急电话、天气与道路官网','phone'],['heltransport','赫尔辛基交通','三种方式与晚间返程','plane']];return `<div class="view-top"><div class="eyebrow">FIELD NOTES</div><h1>随行备忘</h1></div><div class="memo-list">${items.map(([k,n,s,i])=>`<button class="memo-button" data-detail="${k}">${ico(i)}<span><strong>${n}</strong><small>${s}</small></span>${ico('arrow')}</button>`).join('')}</div><div class="mini-info">时区：北京UTC+8；芬兰10/18为UTC+3；挪威10/25起UTC+1；冰岛全年UTC；丹麦11月为UTC+1。欧洲10月25日结束夏令时，手机自动校时后仍核对航班当地时间。</div>`;}
let map=null,mapFilter='all';
function mapPage(){return `<div class="view-top"><div class="eyebrow">ROUTE ATLAS</div><h1>路线地图</h1><p class="intro-text">点位可离线查看；打开导航链接需要联网。</p></div><div class="map-controls"><select id="mapFilter" aria-label="选择日期"><option value="all">北欧全程</option>${DATA.days.map(d=>`<option value="${d.id}">${shortDate(d.date)} ${esc(d.title)}</option>`).join('')}</select><button data-fit>适应路线</button></div><div class="map-wrap"><div id="routeMap" class="map" aria-label="互动路线地图"></div></div><p class="intro-text">线段连接行程点位，公路行驶请打开导航核对。</p><div id="mapPlaces" class="alt-list"></div><button class="small-link" data-view="overview">${ico('back')} 返回全程</button>`;}
function initMap(){if(!window.L){$('#routeMap').textContent='地图加载失败，请使用下方导航链接。';return;}map=L.map('routeMap',{scrollWheelZoom:false,attributionControl:true,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false});L.geoJSON(GEO,{style:{color:'#97b8c9',weight:.7,fillColor:'#f3f6ed',fillOpacity:1}}).addTo(map);map.attributionControl.addAttribution('边界：Natural Earth · datasets/geo-countries · 点位导航：Google Maps');let layer=L.layerGroup().addTo(map);const update=()=>{layer.clearLayers();const select=$('#mapFilter');select.value=String(mapFilter);let ds=mapFilter==='all'?DATA.days.filter(d=>d.id<18):[DATA.days[+mapFilter-1]];let unique=new Set(),bounds=[];for(const d of ds){let ids=d.route;if(d.id===10)ids=(state.variants[10]==='B')?['kef-airport','blue','oddsson']:['kef-airport','oddsson','sky'];if(d.id===1&&state.variants[1]==='A')ids=['hel-airport'];let points=ids.map(k=>DATA.places[k]).filter(p=>p&&(mapFilter!=='all'||p.lon<40));if(points.length>1)L.polyline(points.map(p=>[p.lat,p.lon]),{color:'#4c8baa',weight:2,opacity:.65,dashArray:d.flights?.length?'4 7':null}).addTo(layer);for(const p of points){bounds.push([p.lat,p.lon]);if(unique.has(p.id))continue;unique.add(p.id);const m=L.marker([p.lat,p.lon],{icon:L.divIcon({className:'map-pin',html:String(unique.size),iconSize:[24,24],iconAnchor:[12,12]})}).addTo(layer);m.bindPopup(`<div class="map-popup"><strong>${esc(p.name)}</strong><span>${esc(p.en)}</span><br>${ext(navLink(p),'打开导航','')}${pImage(p.id)?`<br><button data-place="${p.id}">景点介绍 →</button>`:''}</div>`);}}if(bounds.length)map.fitBounds(bounds,{padding:[35,35],maxZoom:12,animate:false});$('#mapPlaces').innerHTML=[...unique].map((k,i)=>{const p=DATA.places[k];return `<div class="alt-row"><strong>${i+1}. ${esc(p.name)}</strong> ${ext(navLink(p),'导航','small-link')}</div>`;}).join('')||'<p class="intro-text">此日仅机场抵达，详见当日安排。</p>';};$('#mapFilter').value=String(mapFilter);$('#mapFilter').onchange=e=>{mapFilter=e.target.value;update();};$('[data-fit]').onclick=update;update();const currentMap=map;requestAnimationFrame(()=>{if(map===currentMap)currentMap.invalidateSize();});}
function render(scroll=true){const retainedChoice=!scroll?$('.choice'):null;if(map){map.stop();map.remove();map=null;}$('#dayRail').innerHTML='<div class="rail-title">18 DAYS / OCT — NOV</div>'+DATA.days.map(d=>`<button class="day-tab ${d.id===state.day&&state.view==='day'?'active':''}" data-day="${d.id}" aria-label="${dateText(d.date)} ${esc(d.title)}" ${d.id===state.day&&state.view==='day'?'aria-current="date"':''}><span class="num">${String(d.id).padStart(2,'0')}</span><span><span class="date">${shortDate(d.date)}</span><span class="label">${esc(d.title)}</span></span></button>`).join('');$('#page').innerHTML=clockBar()+({day:renderDay,overview,orders,memo,map:mapPage})[state.view]();if(retainedChoice&&$('.choice')){$('.choice').replaceWith(retainedChoice);retainedChoice.dataset.selected=state.variants[state.day]||'A';retainedChoice.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.variant===retainedChoice.dataset.selected)));}$('#bottomNav').innerHTML=[['day','日程','calendar'],['overview','全程','map'],['orders','订单','ticket'],['memo','备忘','book']].map(([k,n,i])=>`<button data-view="${k}" class="${state.view===k||(state.view==='map'&&k==='overview')?'active':''}" aria-label="${n}">${ico(i)}<span>${n}</span></button>`).join('');if(state.view==='map')initMap();if(scroll)window.scrollTo({top:0,behavior:'instant'});animateContent(scroll?$('#page'):$('.variant-content'));persist();requestAnimationFrame(drawThread);if(state.view==='day'&&matchMedia('(max-width:760px)').matches){const rail=$('#dayRail'),active=rail.querySelector('.active');if(active)rail.scrollTo({left:active.offsetLeft-rail.clientWidth/2+active.clientWidth/2,behavior:'smooth'});}updateClocks();document.title=`${state.view==='day'?DATA.days[state.day-1].title+' · ':''}北境路书 2026`;}
function drawThread(){document.querySelectorAll('.route-sheet').forEach(sheet=>{const svg=sheet.querySelector('.route-thread');if(!svg)return;svg.setAttribute('viewBox','0 0 100 150');const two=sheet.querySelectorAll('.postcard').length===2;const d=two?'M 89 31 C 103 41, 101 57, 87 67 S 2 73, 10 91':'M 89 31 C 102 43, 99 65, 83 76';for(const p of svg.querySelectorAll('path'))p.setAttribute('d',d);svg.querySelector('.route-nodes').innerHTML=two?'<circle cx="94" cy="55" r="1.8"/><circle cx="16" cy="78" r="1.8"/>':'<circle cx="94" cy="55" r="1.8"/>';});}

new ResizeObserver(()=>requestAnimationFrame(drawThread)).observe($('#page'));
document.addEventListener('load',e=>{if(e.target.tagName==='IMG')drawThread();},true);
function animateContent(el){if(!el||matchMedia('(prefers-reduced-motion:reduce)').matches)return;el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:.55,transform:'translateY(9px)'},{opacity:1,transform:'translateY(0)'}],{duration:360,easing:'cubic-bezier(.16,1,.3,1)'});}
let lastFocus=null,closeTimer=null;
function focusDrawerWhenReady(attempt=0){const overlay=$('#overlay'),drawer=$('.drawer');if(!overlay.classList.contains('open')||overlay.inert||drawer.contains(document.activeElement))return;const button=$('#closeDrawer');if(getComputedStyle(overlay).visibility==='visible'&&button.getClientRects().length)button.focus({preventScroll:true});if(!drawer.contains(document.activeElement)&&attempt<32)requestAnimationFrame(()=>focusDrawerWhenReady(attempt+1));}
function openDrawer(title,body){clearTimeout(closeTimer);lastFocus=document.activeElement;$('#drawerBody').innerHTML=clockBar()+`<h1 id="drawerTitle">${esc(title)}</h1>${body}`;updateClocks();$('#overlay').inert=false;void $('#overlay').offsetWidth;$('#overlay').classList.add('open');animateContent($('#drawerBody'));$('#overlay').setAttribute('aria-hidden','false');$('#mainShell').inert=true;$('#bottomNav').inert=true;$('#topbar').inert=true;document.body.style.overflow='hidden';$('.drawer').scrollTop=0;void $('#overlay').offsetWidth;requestAnimationFrame(()=>focusDrawerWhenReady());}
function closeDrawer(){if(!$('#overlay').classList.contains('open'))return;$('#overlay').classList.remove('open');$('#overlay').setAttribute('aria-hidden','true');$('#overlay').inert=true;$('#mainShell').inert=false;$('#bottomNav').inert=false;$('#topbar').inert=false;document.body.style.overflow='';lastFocus?.focus({preventScroll:true});}
function openPlace(k){const p=DATA.places[k];if(!p)return;const src=pImage(k);openDrawer(p.name,`<p class="detail-en">${esc(p.en)}</p>${src?`<div class="detail-photo"><img src="${src}" alt="${esc(p.name)}" title="${esc(photoCredit(k))}"></div>`:''}<p class="detail-desc">${inline(p.desc)}</p>${p.address?`<div class="address-block">${ico('pin')}<span>${esc(p.address)}</span></div>`:''}<dl class="facts"><div><dt>建议停留</dt><dd>${esc(p.stay||'按当日时间线')}</dd></div><div><dt>游览安排</dt><dd>${esc(p.hours||'以现场开放及天气为准')}</dd></div></dl>${k==='silfra'||k==='cave'||k==='whale'||k==='jokulsarlon'?bookingNavigation(DATA.bookings.find(b=>b.spot===k)) :ext(navLink(p),'打开地图导航','primary-link')}${p.parking?`<div class="detail-block"><h3>停车</h3><p>${inline(p.parking)}</p></div>`:''}${placeTips(p)}`);}
function openHotel(k){const h=DATA.hotels[k];openDrawer(h.cn,`<p class="detail-en">${esc(h.name)}</p><p class="detail-desc">${esc(h.note)}</p><div class="detail-block"><h3>地址</h3><p>${esc(h.address)}</p>${h.phone?`<p>${ext('tel:'+h.phone.replace(/\s/g,''),h.phone,'')}</p>`:''}</div>${ext(hotelLink(k),'酒店导航','primary-link')}<button class="small-link" data-copy="${esc(h.name+'\n'+h.address)}">复制酒店名称与地址 ${ico('check')}</button>`);}
const packing=['护照、签证、驾驶证及车行接受的译件，订单离线备份','四人各一箱；确认各段机票托运行李额度与尺寸','保暖内层、抓绒/羽绒、防风防水外套、帽子、手套','防滑防水鞋；冰洞穿踝部支撑好的鞋，装备听从向导','观鲸与冰洞的自带午餐、水、能量食品','泳衣、干衣袋；Silfra按运营商指引准备保暖内层','银行卡、可用短信手机号；提前测试EasyPark / Parka / Checkit','保温袋与冰袋；28—31日食材按冷链和食用日期分装','充电线、车载充电；取车拍照并核对充电/油量规则'];
const groceries=['主食16人份：米/意面/面条，优先小包装','28日鲜食：鸡蛋、蔬菜及一餐蛋白质','29、30日食材：能可靠冷藏的蛋白质与蔬菜，保温运输','31日常温餐：意面酱、罐头/豆类、耐储蔬菜','四天自行早餐：面包/燕麦、牛奶或常温饮品、水果','29日快艇、30日冰洞与转场日的便携午餐和水','少量油盐、洗洁用品；先核对公寓厨房已有物品'];
function checklist(key,items){return `<div class="checklist">${items.map((s,i)=>`<label class="check-item"><input type="checkbox" data-check="${key}-${i}" ${state.checks[key+'-'+i]?'checked':''}><span>${esc(s)}</span></label>`).join('')}</div>`;}
function helTransportDetail(){return `<p class="detail-desc">10月18日星期日 · 先入住存箱，再决定是否进城。四人往返列车€36–38.40；往返打车约€76–84；列车去打车回约€56–60。出租车须确认酒店上车及返程报价。</p><div class="detail-block"><h3>列车返程 · P线</h3><table class="train-table"><tr><th>中央车站</th><th>机场站</th><th>回酒店约</th></tr><tr><td>21:53 · 主选</td><td>22:27</td><td>22:37–22:42</td></tr><tr><td>22:08 · 一班容错</td><td>22:42</td><td>22:52–22:57</td></tr><tr><td>22:23 · 不建议</td><td>22:57</td><td>23:07–23:12</td></tr><tr><td>次日00:48 · 末班</td><td>01:22</td><td>01:32–01:37</td></tr></table><p>目标21:45到中央车站候车。末班仅作信息备注，无法满足23:00前回酒店。机场站出站后另留10–15分钟步行。</p></div><div class="detail-block"><h3>打车返程</h3><p>21:20查看供车，21:50叫车，22:00前上车，车程留30–45分钟。混合方案叫车不顺时，及时回车站乘21:53 P线。</p></div><div class="detail-block"><h3>出发窗口</h3><p>列车完整夜游需20:15前到中央车站；打车建议20:30前到，最晚20:45。入境、取箱、入住和快餐均不能省，时间不足选A。</p></div><p class="detail-source">按已核对10/12–10/24时刻表安排，出发当天复核停运及站台。${ext('https://www.hsl.fi/en/travelling/route-and-station-maps','HSL线路与时刻','')} · ${ext('https://www.hsl.fi/en/tickets-and-fares','ABC票与票价','')}</p>`;}
function emergency(){return `<div class="callout danger">${ico('phone')}<span><strong>紧急求助</strong>芬兰、冰岛、丹麦：112。挪威：医疗113、火警110、警方112。说明位置、路号和人数。</span></div><div class="rich"><h2>挪威</h2><p>${ext('https://www.yr.no/en','Yr天气','')} · ${ext('https://www.vegvesen.no/trafikk','Vegvesen道路','')} · ${ext('https://www.avinor.no/en/','Avinor机场','')}</p><h2>冰岛</h2><p>${ext('https://en.vedur.is/','气象与预警','')} · ${ext('https://umferdin.is/en','道路状况','')} · ${ext('https://safetravel.is/','SafeTravel','')} · ${ext('https://www.112.is/en','112求助','')} · ${ext('https://www.isavia.is/en','机场','')}</p><h2>芬兰与丹麦</h2><p>${ext('https://en.ilmatieteenlaitos.fi/warnings','芬兰气象预警','')} · ${ext('https://www.finavia.fi/en/airports/helsinki-airport','HEL机场','')} · ${ext('https://www.dmi.dk/','丹麦气象','')} · ${ext('https://www.cph.dk/en','CPH机场','')} · ${ext('https://m.dk/en/','哥本哈根地铁','')}</p><h2>活动与交通中断</h2><p>先去安全室内地点，保存运营商取消通知；按订单渠道处理。道路封闭时不自行绕入非开放山路。路书不自动改订，也不访问私人订单。</p></div><p class="detail-source">${ext('https://www.visitnorway.com/plan-your-trip/travel-tips-a-z/','挪威应急电话官方说明','')} · ${ext('https://www.112.is/en','冰岛112','')} · ${ext('https://politi.dk/en/about-the-police/contact-the-police/emergency-112','丹麦112','')} · ${ext('https://www.suomi.fi/services/phoneservice/112-emergency-number-in-finland-emergency-response-centre-agency-finland/c7cad442-1820-4854-8d40-48536e6d7fcd','芬兰112','')}</p>`;}
function detail(k){if(k==='norway'||k==='iceland')openDrawer(k==='norway'?'挪威自驾操作':'冰岛自驾操作','<div class="rich">'+markdown(DATA.guides[k])+'</div>');else if(k==='heltransport')openDrawer('赫尔辛基往返交通',helTransportDetail());else if(k==='groceries')openDrawer('四晚厨房采购',`<p class="detail-desc">10月28日17:30–18:30在Krónan Vík集中买齐，覆盖28—31日四晚。四间住宿均按已确认有厨房安排。不要用备选景点挤占采购。</p>${checklist('grocery',groceries)}<div class="callout">${ico('bag')}<span>肉类、乳品等全程保持可靠冷藏；长途转场无法保证冷链时，改买常温食品。31日用耐储食材。</span></div>`);else if(k==='packing')openDrawer('出发清单',checklist('packing',packing));else if(k==='emergency')openDrawer('应急资源',emergency());}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-copy]');if(!b)return;const a=b.dataset;if(a.day){const n=+a.day;if(n<1||n>18)return;state.day=n;state.view='day';render();}else if(a.view){state.view=a.view;render();}else if(a.variant){state.variants[state.day]=a.variant;const y=scrollY;render(false);window.scrollTo(0,y);}else if(a.transport){state.transport=a.transport;render(false);}else if(a.place||a.venue)openPlace(a.place||a.venue);else if(a.hotel)openHotel(a.hotel);else if(a.booking){const q=DATA.bookings.find(x=>x.day===+a.booking);openDrawer(q.name,`<p class="detail-en">${dateText(DATA.days[q.day-1].date)} · ${q.people}位</p>${booking(q).replace(/data-booking=/g,'data-reservation=')}<p class="detail-desc">集合位置：${esc(q.place)}。</p>${bookingNavigation(q)}`);}else if(a.notes)openDrawer(DATA.days[+a.notes-1].title+' · 详细说明','<div class="rich">'+markdown(DATA.days[+a.notes-1].notes)+'</div>');else if(a.guide)detail(a.guide);else if(a.detail)detail(a.detail);else if(a.mapday){mapFilter=a.mapday;state.view='map';render();}else if(a.copy){const ta=document.createElement('textarea');ta.value=a.copy;ta.style.cssText='position:fixed;opacity:0';document.body.append(ta);ta.select();let ok=false;try{ok=document.execCommand('copy');}catch{}ta.remove();toast(ok?'已复制地址':'请长按地址复制');}else if(b.id==='closeDrawer')closeDrawer();else if(b.id==='saveHtml')saveHtml();});
document.addEventListener('change',e=>{const k=e.target.dataset.check;if(k){state.checks[k]=e.target.checked;persist();}});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeDrawer();});
document.addEventListener('keydown',e=>{if(!$('#overlay').classList.contains('open'))return;if(e.key==='Escape'){e.preventDefault();closeDrawer();}if(e.key==='Tab'){const f=$$('.drawer button,.drawer a[href],.drawer input,.drawer select,.drawer summary').filter(x=>!x.disabled&&x.offsetParent!==null);const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2300);}
function saveHtml(){const clone=document.documentElement.cloneNode(true);clone.querySelector('#page').innerHTML='';clone.querySelector('#dayRail').innerHTML='';clone.querySelector('#bottomNav').innerHTML='';clone.querySelector('#drawerBody').innerHTML='';clone.querySelector('#overlay').classList.remove('open');clone.querySelector('#overlay').setAttribute('aria-hidden','true');clone.querySelector('#overlay').inert=true;for(const x of ['#mainShell','#bottomNav','#topbar'])clone.querySelector(x).inert=false;clone.querySelector('body').style.overflow='';const url=URL.createObjectURL(new Blob(['<!doctype html>\n'+clone.outerHTML],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='北境路书_2026.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('已保存离线路书');}
/* Calendar selection follows the trip location, independently of saved page selection. */
function tripDateInZone(now,zone){const p=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now),v={};for(const x of p)v[x.type]=x.value;return `${v.year}-${v.month}-${v.day}`;}
function tripAddDate(date,days){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10);}
function tripLocalTimestamp(date,time,zone){const match=time.match(/(\d{1,2}):(\d{2})/);if(!match)return NaN;const [y,m,d]=date.split('-').map(Number),want=Date.UTC(y,m-1,d,+match[1],+match[2]);let utc=want;
 const f=new Intl.DateTimeFormat('en-GB',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
 for(let i=0;i<3;i++){const v={};for(const p of f.formatToParts(new Date(utc)))v[p.type]=p.value;const got=Date.UTC(+v.year,+v.month-1,+v.day,+v.hour,+v.minute,+v.second);utc+=want-got;}return utc;
}
function tripZoneChanges(days){const zones={PKX:'Asia/Shanghai',HEL:'Europe/Helsinki',OSL:'Europe/Oslo',TOS:'Europe/Oslo',LKN:'Europe/Oslo',SVJ:'Europe/Oslo',BOO:'Europe/Oslo',KEF:'Atlantic/Reykjavik',CPH:'Europe/Copenhagen'},changes=[];
 for(const d of days)for(const f of d.flights||[]){const origin=zones[f[1]],target=zones[f[4]];if(!origin||!target)continue;const departDate=tripAddDate(d.date,/前日/.test(f[3])?-1:0),depart=tripLocalTimestamp(departDate,f[3],origin),explicit=f[6].match(/\+(\d+)\s*日/);let arrivalDate=tripAddDate(d.date,explicit?+explicit[1]:0),at=tripLocalTimestamp(arrivalDate,f[6],target);if(at<depart&&!explicit){arrivalDate=tripAddDate(arrivalDate,1);at=tripLocalTimestamp(arrivalDate,f[6],target);}if(Number.isFinite(at))changes.push({at,zone:target,flight:f[0]});}
 return changes.sort((a,b)=>a.at-b.at);
}
function tripToday(now,days,changes){let zone='Asia/Shanghai';for(const c of changes){if(c.at>+now)break;zone=c.zone;}const date=tripDateInZone(now,zone),exact=days.find(d=>d.date===date);const selected=exact||(date<days[0].date?days[0]:days[days.length-1]);return {day:selected.id,date,zone,inTrip:!!exact,boundary:exact?'today':date<days[0].date?'first':'last'};}
const tripCalendarChanges=tripZoneChanges(DATA.days);
let tripLastObservedDate=tripToday(new Date(),DATA.days,tripCalendarChanges).date;
const renderBeforeDateNavigation=render;
function renderDateNavigation(){const current=tripToday(new Date(),DATA.days,tripCalendarChanges),rail=$('#dayRail');
 rail.innerHTML=DATA.days.map(d=>{const day=new Date(d.date+'T12:00:00Z'),weekday=new Intl.DateTimeFormat('zh-CN',{timeZone:'UTC',weekday:'short'}).format(day),date=`${+d.date.slice(5,7)}月${+d.date.slice(8,10)}日`,today=current.inTrip&&current.day===d.id;return `<button class="day-tab calendar-tab ${d.id===state.day?'active':''}" data-day="${d.id}" aria-label="${esc(dateText(d.date))} ${esc(d.title)}${today?' 今天':''}" ${d.id===state.day?'aria-current="page"':''}><span class="day-date-main">${date}</span><span class="day-week">${weekday}${today?' · 今天':''}</span><span class="day-place">${esc(d.title)}</span></button>`;}).join('');
 let jump=document.querySelector('[data-trip-today]');if(!jump){jump=document.createElement('button');jump.className='text-button trip-today';jump.dataset.tripToday='';document.querySelector('.top-actions').prepend(jump);}jump.textContent=current.boundary==='first'?'回到首日':current.boundary==='last'?'回到末日':'回到今天';jump.setAttribute('aria-label',`自动定位${DATA.days.find(d=>d.id===current.day).date}行程`);
 requestAnimationFrame(()=>{const active=rail.querySelector('.active');if(!active)return;if(matchMedia('(max-width:760px)').matches)rail.scrollTo({left:active.offsetLeft-rail.clientWidth/2+active.clientWidth/2,behavior:'instant'});else rail.scrollTo({top:active.offsetTop-rail.clientHeight/2+active.clientHeight/2,behavior:'instant'});});
}
render=function(scroll=true){renderBeforeDateNavigation(scroll);renderDateNavigation();};
function tripSelectToday(){const t=tripToday(new Date(),DATA.days,tripCalendarChanges);tripLastObservedDate=t.date;state.day=t.day;state.view='day';render();}
function tripCheckNewDate(){const t=tripToday(new Date(),DATA.days,tripCalendarChanges);if(t.date!==tripLastObservedDate)tripSelectToday();}
document.addEventListener('click',e=>{if(e.target.closest('[data-trip-today]'))tripSelectToday();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tripCheckNewDate();});
window.addEventListener('pageshow',tripCheckNewDate);
setInterval(tripCheckNewDate,60000);
/* Run on every open; saved A/B choices and checklists are retained. */
state.day=tripToday(new Date(),DATA.days,tripCalendarChanges).day;state.view='day';

/* Planned local-time guidance. It never infers actual activity completion. */
function stepTimeZones(day,row){
 const airportZones={PKX:'Asia/Shanghai',HEL:'Europe/Helsinki',OSL:'Europe/Oslo',TOS:'Europe/Oslo',LKN:'Europe/Oslo',SVJ:'Europe/Oslo',BOO:'Europe/Oslo',KEF:'Atlantic/Reykjavik',CPH:'Europe/Copenhagen'};
 const firstClock=row.time.match(/\d{1,2}:\d{2}/)?.[0];
 const flight=(day.flights||[]).find(f=>row.text.includes(f[0])&&firstClock===f[3].match(/\d{1,2}:\d{2}/)?.[0]);
 if(flight)return {start:airportZones[flight[1]],end:airportZones[flight[4]],flight};
 const i=day.timeline.indexOf(row);let zone=day.tz;
 if(day.id===2&&i>=0&&i<2)zone='Europe/Helsinki';
 if(day.id===10&&i>=0&&i<2)zone='Europe/Oslo';
 if(day.id===16&&i>=0&&i<4)zone='Atlantic/Reykjavik';
 if(day.id===17&&i>=0&&i<6)zone='Europe/Copenhagen';
 return {start:zone,end:zone};
}
function stepWindow(day,row){
 if(/前一晚/.test(row.time))return null;
 const clocks=[...row.time.matchAll(/(\d{1,2}):(\d{2})/g)].map(m=>m[0]);
 if(!clocks.length)return null;
 const z=stepTimeZones(day,row),start=tripLocalTimestamp(day.date,clocks[0],z.start);
 let end=null,deadline=false;
 if(z.flight){const f=z.flight,plus=f[6].match(/\+(\d+)\s*日/);end=tripLocalTimestamp(tripAddDate(day.date,plus?+plus[1]:0),f[6],z.end);if(end<start)end=tripLocalTimestamp(tripAddDate(day.date,1),f[6],z.end);}
 else if(clocks.length>1)end=tripLocalTimestamp(day.date,clocks[clocks.length-1],z.end);
 else if(/最迟|前$|^[^\d]*至\d/.test(row.time)){end=start;deadline=true;}
 if(end!==null&&end<start)end+=86400000;
 return {start,end,deadline,zone:z.start};
}
function timeline(rows){
 const day=DATA.days[state.day-1];
 return `<div class="timeline">${rows.map(r=>{const w=stepWindow(day,r);return `<div class="timeline-row${r.critical?' time-critical':''}"${w?` data-step-start="${w.start}"${w.end!==null?` data-step-end="${w.end}"`:''}${w.deadline?' data-step-deadline="true"':''}`:''}><div class="timeline-time">${inline(r.time)}</div><div class="timeline-text"><div class="timeline-heading"><strong class="step-title">${esc(r.stepTitle)}</strong><span class="step-state" aria-live="off"></span>${r.critical?`<span class="step-key" title="${esc(r.critical)}">关键时间</span>`:''}</div>${timelineText(r)}</div></div>`;}).join('')}</div>`;
}
function plannedSteps(nodes){
 const rows=nodes.map((node,index)=>({node,index,start:Number(node.dataset.stepStart),end:node.hasAttribute('data-step-end')?Number(node.dataset.stepEnd):null,deadline:node.hasAttribute('data-step-deadline')}));
 for(let i=0;i<rows.length;i++){const r=rows[i];if(r.deadline){const prev=rows.slice(0,i).reverse().find(x=>x.start<r.start);r.start=prev&&prev.end!==null&&prev.end<r.end?Math.max(prev.end,r.end-3600000):r.end-1800000;}
  if(r.end===null){const next=rows.slice(i+1).find(x=>x.start>r.start);r.end=next?next.start:Math.min(r.start+3600000,tripLocalTimestamp(DATA.days[state.day-1].date,'23:59',DATA.days[state.day-1].tz));}
  if(r.end<=r.start)r.end=r.start+60000;
 }return rows;
}
function updateTimelinePriority(now=new Date(),focus=false){
 const all=[...document.querySelectorAll('.timeline-row')];
 for(const node of all){node.classList.remove('is-current','is-next');node.removeAttribute('aria-current');const badge=node.querySelector('.step-state');if(badge)badge.textContent='';}
 if(state.view!=='day')return;
 const today=tripToday(now,DATA.days,tripCalendarChanges);if(!today.inTrip||today.day!==state.day)return;
 const rows=plannedSteps(all.filter(n=>n.hasAttribute('data-step-start'))),time=+now;
 const current=rows.filter(r=>r.start<=time&&time<r.end).sort((a,b)=>b.start-a.start||b.index-a.index)[0];
 const next=rows.filter(r=>r.start>time).sort((a,b)=>a.start-b.start||a.index-b.index)[0];
 for(const [row,cls,label]of [[current,'is-current','当前'],[next,'is-next','下一段']])if(row){row.node.classList.add(cls);row.node.querySelector('.step-state').textContent=label;if(cls==='is-current')row.node.setAttribute('aria-current','step');}
 const target=current||next;
 if(focus&&target){requestAnimationFrame(()=>requestAnimationFrame(()=>{if(document.contains(target.node)&&state.view==='day')target.node.scrollIntoView({block:'center',behavior:'instant'});}));}
}
const renderBeforeTimelinePriority=render;
render=function(scroll=true){renderBeforeTimelinePriority(scroll);updateTimelinePriority(new Date(),false);};
setInterval(()=>updateTimelinePriority(),30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateTimelinePriority();});
window.addEventListener('pageshow',()=>updateTimelinePriority(new Date(),false));

